function codePointLength(value) {
  let length = 0;
  let i = 0;
  while (i < value.length) {
    const first = value.charCodeAt(i++);
    if (first >= 0xd800 && first <= 0xdbff && i < value.length) {
      const second = value.charCodeAt(i);
      if (second >= 0xdc00 && second <= 0xdfff) i++;
    }
    length++;
  }
  return length;
}
